"""Complete 20 original general-examination questions."""
from create_exam_general_signs import rows,q,CM,HA,CY,ref
from qbank_authoring import finalize
OH=ref('ESC practical syncope guidance: orthostatic assessment','https://academic.oup.com/eurheartj/article/39/21/e43/4939242')

q('Bilateral dependent pitting edema is present with elevated JVP and a congested liver. Which mechanism is most strongly supported?', 'Increased systemic venous hydrostatic pressure',[
 ('Isolated low oncotic pressure as proven by pitting alone','Low albumin can cause edema, but the elevated venous signs support congestion.'),('Pure lymphedema without any vascular contribution','The overall venous-congestion pattern favors a systemic hydrostatic mechanism.'),('Simple adipose enlargement','Pitting and associated venous findings indicate interstitial fluid.')],
 'Interpret edema with the venous and organ examination','**Pitting reflects mobile interstitial fluid, not a unique cause.**',['Hydrostatic, oncotic, permeability and lymphatic mechanisms can overlap.','Distribution and associated findings narrow the differential.'],'**Assess cardiac, renal, hepatic and medication contributors.**',['Do not equate visible edema with adequate intravascular perfusion.','Use weight and fluid trends with the examination.'],[['Pitting','Fluid property'],['High JVP','Venous-pressure clue'],['Mechanism','Integrated rather than sign alone']],[CM],style='clinical_scenario')

q('A patient has acute unilateral calf swelling after surgery. Homan’s sign is absent. Which interpretation is correct?', 'DVT remains possible; use validated probability assessment and appropriate testing',[
 ('An absent Homan’s sign excludes DVT','The sign is not a reliable exclusion test.'),('Calf pain alone confirms DVT without imaging or probability assessment','Several conditions can mimic DVT.'),('Only bilateral swelling can be thrombotic','DVT commonly presents unilaterally.')],
 'Do not rely on a traditional low-accuracy maneuver','**Clinical examination informs probability but does not usually settle DVT.**',['Review immobility, cancer, prior thrombosis and alternative diagnoses.','Use an evidence-based D-dimer/ultrasound pathway.'],'**Arrange timely testing and interim treatment when indicated.**',['Assess bleeding risk and local protocol.','Investigate PE symptoms urgently if present.'],[['Homan sign','Unreliable'],['Clinical probability','Structured assessment'],['Confirmation','Appropriate ultrasound pathway']],[ref('NICE venous thromboembolic disease guideline','https://www.nice.org.uk/guidance/ng158/chapter/recommendations')],style='clinical_scenario')

q('Supine BP is 142/82 mmHg and after 2 minutes standing it is 116/72 mmHg with lightheadedness. Which interpretation is appropriate?', 'The sustained 26-mmHg systolic fall meets the conventional criterion for orthostatic hypotension',[
 ('The systolic change is too small because only a 40-mmHg fall counts','The usual classical threshold is at least twenty systolic or ten diastolic within three minutes.'),('The normal-range standing systolic pressure excludes a significant postural drop','The fall itself and symptoms matter.'),('The result establishes POTS instead of hypotension','POTS is not defined by this sustained hypotensive pattern.')],
 'Measure the change under a standardized posture protocol','**Classical orthostatic hypotension is a sustained pressure fall after standing or tilt.**',['Baseline rest and repeated standing measurements improve interpretation.','Symptoms and delayed patterns may require further assessment.'],'**Review volume, drugs and autonomic causes.**',['Do not infer a single etiology from the pressure change alone.','Use standing pressure and fall risk in management decisions.'],[['Systolic drop','26 mmHg'],['Timing','Within 3 minutes'],['Next step','Cause and safety assessment']],[OH],style='clinical_scenario')

q('A cuff measurement detects Korotkoff sounds only during expiration at 118 mmHg, but during the entire respiratory cycle at 102 mmHg. What is the measured pulsus paradoxus?', '16 mmHg',[
 ('8 mmHg','This halves the difference without a physiological basis.'),('102 mmHg','This is the lower cuff pressure, not the respiratory difference.'),('220 mmHg','This adds rather than subtracts the two pressures.')],
 'The difference estimates respiratory systolic variation','**Subtract the all-cycle sound threshold from the expiration-only threshold.**',['The result here is one hundred eighteen minus one hundred two.','A marked inspiratory fall can occur in tamponade and severe obstructive lung disease.'],'**Interpret in the relevant cardiopulmonary context.**',['Do not diagnose tamponade from this sign alone.','Technique, rhythm and breathing effort affect measurement.'],[['Expiration-only threshold','118'],['All-cycle threshold','102'],['Difference','16 mmHg']],[ref('Stanford Medicine 25: pulsus paradoxus','https://stanfordmedicine25.stanford.edu/the25/bppp.html')],style='clinical_scenario')

q('The apical heart rate is 126/min while a simultaneously counted radial rate is 104/min. What is the pulse deficit?', '22/min',[
 ('104/min','That is the radial pulse rate.'),('126/min','That is the apical rate.'),('230/min','The deficit is a difference, not a sum.')],
 'Some electrical/mechanical beats fail to create a palpable peripheral pulse','**Simultaneous counts avoid changes over time confounding the comparison.**',['AF and ectopic beats can produce a deficit through variable filling/output.','The deficit does not identify the rhythm without further assessment.'],'**Obtain an ECG and assess perfusion and symptoms.**',['Do not assume the radial rate alone equals ventricular activation rate.','Review the rate/rhythm and underlying cause.'],[['Apical','126'],['Radial','104'],['Deficit','22']],[CM],style='clinical_scenario')

q('Why should respiratory rate be measured carefully rather than routinely entered as a default normal value?', 'It is a sensitive physiological observation that can reveal deterioration even when oxygen saturation is acceptable',[
 ('A normal SpO2 makes respiratory rate irrelevant','Oxygenation does not measure ventilation, effort or compensation for acidosis.'),('Tachypnea always proves primary lung disease','Metabolic, cardiac, infectious and other causes are possible.'),('A respiratory rate alone provides the exact PaCO2','Rate and alveolar ventilation are not interchangeable.')],
 'A simple observation can reveal several mechanisms','**Rate, depth, rhythm and work of breathing should be considered together.**',['Count unobtrusively to reduce voluntary alteration.','A full interval is useful when the rhythm is irregular.'],'**Interpret changes against the clinical context and baseline.**',['Assess pain, fever, acidosis and cardiopulmonary causes.','Use gases when ventilation or acid-base status is uncertain.'],[['Rate','Physiological signal'],['SpO2','Oxygenation only'],['Assessment','Pattern and cause']],[CM])

q('An older patient has reduced skin recoil over the hand but otherwise uncertain fluid findings. What is the appropriate conclusion?', 'Age-related loss of elasticity limits skin-turgor assessment; integrate history, examination and laboratory information',[
 ('The hand finding proves severe dehydration','Age and local skin changes reduce specificity.'),('Normal skin recoil would exclude all water deficit','No single sign is sufficiently reliable.'),('Skin turgor accurately predicts the exact sodium concentration','Water and sodium states cannot be quantified that way.')],
 'A familiar sign may perform poorly in a specific population','**Skin elasticity declines with age.**',['Mouth dryness, urine findings and vital signs also have limitations.','Water deficit and intravascular depletion are related but distinct concepts.'],'**Use the overall intake/loss history and physiological assessment.**',['Review weight trend and relevant chemistry.','Reassess response carefully if fluid is given.'],[['Skin turgor','Age-confounded'],['Water deficit','Not identical to low circulating volume'],['Assessment','Multiple sources of evidence']],[ref('Clinical Methods examination reference','https://www.ncbi.nlm.nih.gov/books/NBK201/')],style='clinical_scenario')

q('A patient with ascites and edema has an apparently normal BMI but visible temporal and proximal muscle wasting. Which interpretation is most appropriate?', 'Fluid accumulation can conceal loss of muscle and nutritional reserve',[
 ('Normal BMI excludes malnutrition or sarcopenia','Body weight can be distorted by fluid.'),('Edema proves adequate protein and energy stores','Edema does not measure nutritional reserve.'),('Only body weight matters and muscle examination is unnecessary','Functional and muscle assessment add important information.')],
 'Separate body mass from body composition','**Water can increase weight while lean tissue is being lost.**',['Assess dietary intake, weight history and muscle function.','Disease-related inflammation can contribute to wasting.'],'**Use a structured nutritional assessment.**',['Consider refeeding risk before rapid nutritional escalation.','Do not infer nutritional recovery solely from increasing fluid-related weight.'],[['Weight','Includes excess fluid'],['Muscle','Can decline simultaneously'],['Assessment','Intake, composition and function']],[CM],style='clinical_scenario')

q('A prolonged capillary refill is found in a cold examination room. Which statement is correct?', 'It can support impaired peripheral perfusion, but temperature, technique and other findings affect interpretation',[
 ('It establishes low cardiac output quantitatively','It is not a direct cardiac-output measurement.'),('It is unaffected by ambient temperature','Cold can alter peripheral circulation and the result.'),('A normal result excludes all shock states','Perfusion abnormalities can be heterogeneous and signs are imperfect.')],
 'Standardization makes serial bedside signs more useful','**Capillary refill reflects peripheral flow under the conditions of measurement.**',['Use consistent pressure, site and timing when trending.','Integrate blood pressure, mentation, urine output and other perfusion evidence.'],'**Treat the underlying physiology rather than one isolated sign.**',['Recheck after appropriate warming or resuscitation.','Do not equate improvement in one region with guaranteed whole-body recovery.'],[['Confounders','Temperature/technique'],['Value','Peripheral perfusion clue'],['Use','Integrated serial assessment']],[CM])

q('A febrile patient has a slower pulse than expected for the temperature. Which inference is most accurate?', 'Relative bradycardia is a contextual clue with infectious, medication and other explanations, not a pathogen-specific diagnosis',[
 ('It uniquely establishes enteric fever','Several infections and noninfectious factors can produce the relationship.'),('It excludes serious infection','Serious disease can occur despite a relatively slow pulse.'),('It proves complete heart block without ECG assessment','The rhythm and conduction require direct assessment.')],
 'A pulse–temperature relationship is not an organism assay','**Rate is affected by baseline fitness, drugs, conduction and systemic disease.**',['Check actual measurement timing and rhythm.','Review beta blockers and other rate-limiting drugs.'],'**Use exposure and the wider syndrome to guide investigation.**',['Obtain ECG or targeted microbiology when indicated.','Avoid narrowing the differential prematurely.'],[['Finding','Relative rate–temperature mismatch'],['Differential','Infection/drugs/conduction and others'],['Limit','Not pathogen-specific']],[CM])

if __name__=='__main__':finalize('Clinical Examination',1,'General Examination','exam-general',rows,20)
